import{z as s,x as A,o,c as B,q as i,j as E,D as r,d as l,s as m,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"相干与非相干传递函数","description":"","frontmatter":{"title":"相干与非相干传递函数","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ctf-otf.md","filePath":"litho/ctf-otf.md","lastUpdated":1791063341000}'),h={name:"litho/ctf-otf.md"};function d(p,a,F,T,f,C){const e=A("Mermaid");return o(),B("div",null,[a[2]||(a[2]=i('<h1 id="相干与非相干传递函数" tabindex="-1">相干与非相干传递函数 <a class="header-anchor" href="#相干与非相干传递函数" aria-label="Permalink to &quot;相干与非相干传递函数&quot;">​</a></h1><div class="epigraph"><p>点扩散在空域卷积；它的傅里叶伙伴在频域相乘。相干乘的是光瞳，非相干乘的是光瞳的自相关。</p><footer>—— Goodman 对 CTF 与 OTF 的定义；光刻读法对照 Mack 的 MTF 讨论</footer></div><p><a href="/litho/psf-airy">上一课</a>把圆孔核叫做 Airy。缺口是：后课要扫节距、要读「哪根齿还在」，必须把核翻回频率轴，并分清<strong>相干传递</strong>与<strong>非相干传递</strong>不是一条曲线。<a href="/litho/mtf-optics">MTF</a>已经用正弦物说过调制；本课补的是与 PSF 成对的定义，以及部分相干为什么不能只用其中一条。Sparrow 两种两点判据留给<a href="/litho/sparrow-criterion">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>卷积定理要求：\\(h\\) 的傅里叶是 \\(H\\)。相干成像对场线性，</p> \\[\\mathrm{CTF}(\\mathbf{f})=P(\\mathbf{f}), \\]<p>截止 \\(\\mathrm{NA}/\\lambda\\)，通带里还可以带像差相位。非相干成像对强度线性，光学传递函数</p> \\[\\mathrm{OTF}(\\mathbf{f})=\\frac{\\iint P(\\boldsymbol{\\xi})P^*(\\boldsymbol{\\xi}-\\mathbf{f})\\,d^2\\boldsymbol{\\xi}}{\\iint |P|^2}, \\]<p>即光瞳的归一化自相关，截止 \\(2\\mathrm{NA}/\\lambda\\)。MTF \\(=|\\mathrm{OTF}|\\)。缺口因此是这对名字与支撑，不是再画一次 Airy 截面。</p><p>产线照明是部分相干：强度对物<strong>不是</strong>线性滤波，完整对象是 TCC。单条 CTF 或单条 OTF 都只是极限切片。把 MTF 验收曲线直接叫成「本层能印的节距」，等于又发明了一条没有胶、没有 \\(\\sigma\\) 的 \\(k_1\\)。</p><h3 id="通带形状不同" tabindex="-1">通带形状不同 <a class="header-anchor" href="#通带形状不同" aria-label="Permalink to &quot;通带形状不同&quot;">​</a></h3><p>圆孔 CTF 在截止内接近矩形（无像差时振幅为 1）。圆孔 OTF 从 1 近似三角降到 \\(2\\mathrm{NA}/\\lambda\\) 处的 0。同一物频率 \\(f\\)，相干通道可能仍满通，非相干通道已经只剩自相关的尾巴。斜照明平移的是 CTF 相对 \\(T\\) 的窗；OTF 没有「斜照明」这一说，因为非相干源已经填满光瞳。</p><p><span class="marginnote">OTF 可以为负（对比反转），MTF 取模会丢掉符号。光刻里反转意味着峰谷对调，阈值切错边。主干 MTF 课已经警告过；本课把它钉在 OTF 的定义里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 PSF 出发：\\(\\mathrm{CTF}=\\mathcal{F}\\{h\\}\\)，\\(\\mathrm{OTF}=\\mathcal{F}\\{|h|^2\\}\\)（再归一到零频为 1）。这就是为什么上一课要先有核。有像差时 \\(P\\) 带相位，OTF 掉、并可能振荡；切趾改 \\(|P|\\)，自相关变，OTF 旁瓣改形状。</p><p>部分相干：对每个源点用一个平移后的 CTF 做相干成像，强度相加。有效「正弦传递」介于 CTF 与 OTF 之间，随 \\(\\sigma\\) 连续变——与<a href="/litho/coherence-sigma">相干因子</a>是同一旋钮的频率语言。定量工艺仍回 NILS 与 TCC，本课不替代。</p>',16)),(o(),E(n,null,{default:r(()=>[m(e,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22PSF%20h%22%5D%20--%3E%20CTF%5B%22CTF%20%3D%20P%22%5D%0A%20%20H%20--%3E%20OTF%5B%22OTF%20%3D%20P%20%E2%8B%86%20P%22%5D%0A%20%20CTF%20--%3E%20COH%5B%22%E7%9B%B8%E5%B9%B2%E6%88%AA%E6%AD%A2%20NA%2F%CE%BB%22%5D%0A%20%20OTF%20--%3E%20INC%5B%22%E9%9D%9E%E7%9B%B8%E5%B9%B2%E6%88%AA%E6%AD%A2%202NA%2F%CE%BB%22%5D%0A%20%20SIG%5B%22%CF%83%22%5D%20--%3E%20PC%5B%22%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%EF%BC%9A%E4%BB%8B%E4%BA%8E%E4%B8%A4%E8%80%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h3",{id:"与-hopkins-的接口",tabindex:"-1"},[l("与 Hopkins 的接口 "),t("a",{class:"header-anchor",href:"#与-hopkins-的接口","aria-label":'Permalink to "与 Hopkins 的接口"'},"​")],-1)),a[4]||(a[4]=t("p",null,"完全相干：\\(\\mathrm{TCC}(\\mathbf{f}_1,\\mathbf{f}_2)=P(\\mathbf{f}_1)P^*(\\mathbf{f}_2)\\)，即一对 CTF。完全非相干：TCC 只依赖差频，退化为 OTF。部分相干保留四维。后课 Abbe 对 Hopkins、SOCS，都只是在这条轴上选计算顺序，不改定义。",-1)),a[5]||(a[5]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=t("p",null,"非相干 OTF 在高频变小，几何图像是：频率 \\(f\\) 对应光瞳里相距 \\(f\\) 的两点；两点都要落在孔径内才有相关面积。孔径是圆，能放下的最大距离是直径，故截止加倍。相干没有「两点相关」，只有「该频率的平面波进不进瞳」，故截止是半径。",-1)),a[7]||(a[7]=t("p",null,"这就是密节距先死的传递机制。一维线栅只碰径向的一条切片；二维孔同时要 \\(x\\)、\\(y\\) 的传递，下一课序会用到，本课先把轴准备好。",-1)),a[8]||(a[8]=t("p",null,"为什么 OTF 的截止是 \\(2\\mathrm{NA}/\\lambda\\)、恰好是 CTF 的两倍？几何图像是「光瞳里放得下多远的一对点」：非相干通道每个频率要靠光瞳内两个位置的振幅互相重叠出相关面积，圆孔里两点最大间距是直径；相干通道只问单个频率分量进不进瞳，最大距离是半径。",-1)),(o(),E(n,null,{default:r(()=>[m(e,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%89%A9%E9%A2%91%E7%8E%87%20f%22%5D%20--%3E%20Q%7B%22%E6%88%90%E5%83%8F%E9%80%9A%E9%81%93%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%9B%B8%E5%B9%B2%22%7C%20C1%5B%22%E5%8F%AA%E9%9C%80%E8%AF%A5%E5%B9%B3%E9%9D%A2%E6%B3%A2%E5%8D%95%E7%82%B9%E8%BF%9B%E7%9E%B3%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%9C%80%E5%A4%A7%E5%8F%AF%E7%94%A8%E8%B7%9D%E7%A6%BB%20%3D%20%E5%8D%8A%E5%BE%84%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E6%88%AA%E6%AD%A2%20NA%2F%CE%BB%22%5D%0A%20%20Q%20--%3E%7C%22%E9%9D%9E%E7%9B%B8%E5%B9%B2%22%7C%20I1%5B%22%E9%9C%80%E5%85%89%E7%9E%B3%E5%86%85%E7%9B%B8%E8%B7%9D%20f%20%E7%9A%84%E4%B8%A4%E7%82%B9%E9%83%BD%E5%9C%A8%E5%AD%94%E5%86%85%22%5D%0A%20%20I1%20--%3E%20I2%5B%22f%20%E8%B6%8A%E5%A4%A7%EF%BC%8C%E9%87%8D%E5%8F%A0%E9%9D%A2%E7%A7%AF%E8%B6%8A%E5%B0%8F%22%5D%0A%20%20I2%20--%3E%20I3%5B%22f%20%3D%20%E7%9B%B4%E5%BE%84%E5%A4%84%E9%87%8D%E5%8F%A0%E5%BD%92%E9%9B%B6%22%5D%0A%20%20I3%20--%3E%20I4%5B%22%E6%88%AA%E6%AD%A2%202NA%2F%CE%BB%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=i('<p><span class="marginnote">直觉类比：CTF 像门卫查一张票——某个频率的平面波进得来光瞳就传；OTF 像凑一对票——该频率要靠光瞳里两个位置各出一员「握手」才能产生强度调制。凑对自然比单张进门难，所以截止距离从半径变成直径，数字上翻倍。</span></p><p><span class="marginnote">数字实例：取 \\(\\lambda=13.5\\) nm、\\(\\mathrm{NA}=0.33\\)：相干截止 \\(\\mathrm{NA}/\\lambda\\approx 24.4\\ \\mu\\mathrm{m}^{-1}\\)，对应周期约 \\(41\\) nm；非相干截止 \\(2\\mathrm{NA}/\\lambda\\approx 48.9\\ \\mu\\mathrm{m}^{-1}\\)，对应周期约 \\(20.5\\) nm。同一台镜头，两条通道的「听得见的最高频率」差一倍——报告截止时必须先声明是哪条。</span></p><p><span class="marginnote">常见误区：初学者容易拿「非相干截止对应 \\(\\lambda/2\\mathrm{NA}\\) 节距」直接当工艺能印的最密集线。产线照明是部分相干，密集线由 TCC 与胶阈值共同决定，单条 OTF 曲线给不出这个数——把三条截止写成一个 \\(k_1\\) 口诀，就是本课开头警告的那类错误。</span></p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>正弦语言：非相干用 OTF/MTF，相干用 CTF。部分相干默认 TCC，需要时才画一条有效调制–节距曲线，并声明 \\(\\sigma\\)。不要在后课把三条截止写成一个数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>传递函数是等晕标量光学的对象。矢量成像、薄膜、胶扩散会再乘各自的核，那些核不是 CTF。禁止把未公开的镜头「衍射极限 MTF」表当作本课数据；Goodman 的圆孔 OTF 与 Mack 的光刻读法已经够用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CTF 即光瞳，截止 \\(\\mathrm{NA}/\\lambda\\)；OTF 即光瞳自相关，截止 \\(2\\mathrm{NA}/\\lambda\\)。</li><li>MTF 是 \\(|\\mathrm{OTF}|\\)，可能丢掉对比反转的符号。</li><li>部分相干介于两者之间，完整核是 TCC。</li><li>PSF 与传递函数是傅里叶对，不是两套物理。</li><li>下一课：两点分辨的 Sparrow 对 Rayleigh。</li><li>出处：Goodman；Mack；Hopkins (1953) 的相干/非相干极限。</li></ul>',9))])}const u=s(h,[["render",d]]);export{D as __pageData,u as default};
